/**
 * src/agents/tx-2-imp-1/prompts/action-05.ts
 * 
 * Action 5: 優先度順に整理した朝会資料を自動生成
 * 
 * tx_2_imp_1 契約に基づき、抽出・分類済み課題を優先度順に整理し、
 * 朝会用資料として構造化したプロンプトを生成する。
 */

export const ACTION_05_PROMPT_VERSION = "1.0.0";

export interface Action05PromptInput {
  /**
   * 優先度付け済みの課題リスト
   * 各課題は優先度スコア、カテゴリ、影響範囲を含む
   */
  prioritizedIssues: Array<{
    id: string;
    title: string;
    description: string;
    category: string;
    priority: number;
    severity: "critical" | "high" | "medium" | "low";
    impactScope: string;
    assignee?: string;
    dueDate?: string;
  }>;

  /**
   * 朝会の実施日時
   */
  meetingDateTime: string;

  /**
   * 部長の名前
   */
  directorName: string;

  /**
   * チーム名
   */
  teamName: string;

  /**
   * 前回朝会からの経過日数
   */
  daysSinceLast?: number;

  /**
   * 未提出メンバーのリスト
   */
  nonSubmittedMembers?: Array<{
    name: string;
    email: string;
  }>;

  /**
   * 朝会資料のフォーマット指定
   */
  outputFormat?: "markdown" | "html" | "json";
}

export interface Action05PromptOutput {
  /**
   * 生成されたプロンプト文字列
   */
  prompt: string;

  /**
   * プロンプトのメタデータ
   */
  metadata: {
    version: string;
    generatedAt: string;
    inputHash: string;
  };
}

/**
 * Action 05 プロンプトを生成する
 * 
 * 優先度付け済みの課題リストを受け取り、朝会用資料として
 * 構造化・整理したプロンプトを生成する。
 * 
 * @param input - プロンプト生成に必要な入力データ
 * @returns 生成されたプロンプトとメタデータ
 */
export function buildAction05Prompt(input: Action05PromptInput): Action05PromptOutput {
  const {
    prioritizedIssues,
    meetingDateTime,
    directorName,
    teamName,
    daysSinceLast = 1,
    nonSubmittedMembers = [],
    outputFormat = "markdown",
  } = input;

  // 優先度別にグループ化
  const criticalIssues = prioritizedIssues.filter(
    (issue) => issue.severity === "critical"
  );
  const highIssues = prioritizedIssues.filter(
    (issue) => issue.severity === "high"
  );
  const mediumIssues = prioritizedIssues.filter(
    (issue) => issue.severity === "medium"
  );
  const lowIssues = prioritizedIssues.filter(
    (issue) => issue.severity === "low"
  );

  // カテゴリ別にグループ化
  const issuesByCategory = prioritizedIssues.reduce(
    (acc, issue) => {
      if (!acc[issue.category]) {
        acc[issue.category] = [];
      }
      acc[issue.category].push(issue);
      return acc;
    },
    {} as Record<string, typeof prioritizedIssues>
  );

  // 非提出者情報の整形
  const nonSubmittedSection =
    nonSubmittedMembers.length > 0
      ? `
## 未提出メンバー（${nonSubmittedMembers.length}名）

${nonSubmittedMembers.map((member) => `- ${member.name} (${member.email})`).join("\n")}

**対応**: 自動催促通知を送信済み。本朝会開始前に再度確認してください。
`
      : "";

  // 優先度別セクション
  const prioritySections = [
    {
      title: "🔴 緊急対応が必要（Critical）",
      issues: criticalIssues,
      count: criticalIssues.length,
    },
    {
      title: "🟠 高優先度（High）",
      issues: highIssues,
      count: highIssues.length,
    },
    {
      title: "🟡 中優先度（Medium）",
      issues: mediumIssues,
      count: mediumIssues.length,
    },
    {
      title: "🟢 低優先度（Low）",
      issues: lowIssues,
      count: lowIssues.length,
    },
  ]
    .filter((section) => section.count > 0)
    .map((section) => {
      const issueList = section.issues
        .map(
          (issue) =>
            `
### ${issue.title}
- **ID**: ${issue.id}
- **カテゴリ**: ${issue.category}
- **説明**: ${issue.description}
- **影響範囲**: ${issue.impactScope}
- **優先度スコア**: ${issue.priority}
${issue.assignee ? `- **担当**: ${issue.assignee}` : ""}
${issue.dueDate ? `- **期限**: ${issue.dueDate}` : ""}
`
        )
        .join("\n");

      return `
## ${section.title}

**件数**: ${section.count}件

${issueList}
`;
    })
    .join("\n");

  // カテゴリ別サマリー
  const categorySummary = Object.entries(issuesByCategory)
    .map(
      ([category, issues]) =>
        `- **${category}**: ${issues.length}件 (Critical: ${issues.filter((i) => i.severity === "critical").length}, High: ${issues.filter((i) => i.severity === "high").length})`
    )
    .join("\n");

  // メインプロンプト生成
  const prompt = `
# 朝会資料 - 課題優先度別整理

**生成日時**: ${new Date().toISOString()}
**朝会実施日時**: ${meetingDateTime}
**チーム**: ${teamName}
**部長**: ${directorName}
**集計期間**: 過去${daysSinceLast}日間

---

## 📊 サマリー

**総課題件数**: ${prioritizedIssues.length}件

### 優先度別集計
- 🔴 Critical: ${criticalIssues.length}件
- 🟠 High: ${highIssues.length}件
- 🟡 Medium: ${mediumIssues.length}件
- 🟢 Low: ${lowIssues.length}件

### カテゴリ別集計
${categorySummary}

---

## 📋 優先度別課題一覧

${prioritySections}

---

${nonSubmittedSection}

---

## 📌 朝会での推奨アジェンダ

1. **Critical課題の即時対応確認** (${criticalIssues.length}件)
   - 各課題の現状と対応方針を確認
   - 必要なリソース配分を決定

2. **High優先度課題の進捗確認** (${highIssues.length}件)
   - 本日中の対応開始を指示

3. **その他課題の共有** (${mediumIssues.length + lowIssues.length}件)
   - 今週中の対応スケジュールを確認

4. **未提出メンバーへの対応** (${nonSubmittedMembers.length}名)
   - 提出催促と期限設定

---

## 🔧 生成ルール

このプロンプトは以下のルールに基づいて自動生成されました：

- 優先度スコアが高い順に課題を整理
- 同一優先度内ではカテゴリ別に分類
- Critical課題は即座に部長に通知
- 未提出メンバーは自動催促対象
- 朝会資料は${outputFormat}形式で出力

---

**注記**: このプロンプトは AI エージェントにより自動生成されています。
部長による最終確認と修正を推奨します。
`;

  // 入力データのハッシュ値を簡易計算
  const inputHash = generateSimpleHash(JSON.stringify(input));

  return {
    prompt,
    metadata: {
      version: ACTION_05_PROMPT_VERSION,
      generatedAt: new Date().toISOString(),
      inputHash,
    },
  };
}

/**
 * 簡易的なハッシュ値を生成する
 * @param input - ハッシュ対象の文字列
 * @returns ハッシュ値
 */
function generateSimpleHash(input: string): string {
  let hash = 0;
  for (let i = 0; i < input.length; i++) {
    const char = input.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return Math.abs(hash).toString(16);
}
